/**
 * Smart Scan Strategy - Synthetic Simulation Engine
 * Manages central simulation state, tick loop, and synthetic telemetry calculations.
 * 
 * NOTE: All data generated by this module is purely synthetic for UI/judging demonstration.
 */

// Single central simulation state object
const simulationState = {
    running: false,
    timerId: null,
    step: 0,
    episode: 1,
    speedMs: 500, // Default 2x speed (500ms per tick)
    numBands: 20,
    currentBand: 1,
    activeStrategy: "AI (PPO)",

    // Synthetic Target Band Occupancy Map (purely simulated channel activity)
    occupiedBands: [3, 7, 12, 18],

    // Current Synthetic AI Metrics
    aiMetrics: {
        detectionRate: 0.0,    // %
        detectionTime: 0.0,    // seconds
        energyConsumption: 0.0,// synthetic units
        cumulativeReward: 0.0  // RL reward points
    },

    // Current Synthetic Baseline Metrics (Sequential Scan)
    baseMetrics: {
        detectionRate: 0.0,
        detectionTime: 0.0,
        energyConsumption: 0.0,
        cumulativeReward: 0.0
    },

    // 20 Spectrum Band States: "IDLE", "SELECTED", "OBSERVED", "OCCUPIED"
    bands: [],

    // Scan History Table (Max 15 items)
    history: [],

    // Console Activity Events
    events: [],

    // Time-series history for Plotly line charts
    chartHistory: {
        steps: [],
        aiDetection: [],
        baseDetection: [],
        aiEnergy: [],
        baseEnergy: [],
        aiReward: [],
        baseReward: []
    }
};

/**
 * Initialize simulation state with baseline data
 */
function initSimulation() {
    simulationState.step = 0;
    simulationState.episode = 1;
    simulationState.currentBand = 1;
    
    // Initial metric values
    simulationState.aiMetrics = {
        detectionRate: 0.0,
        detectionTime: 5.0,
        energyConsumption: 0.0,
        cumulativeReward: 0.0
    };
    
    simulationState.baseMetrics = {
        detectionRate: 0.0,
        detectionTime: 5.0,
        energyConsumption: 0.0,
        cumulativeReward: 0.0
    };

    // Build 20 synthetic spectrum bands
    simulationState.bands = [];
    for (let i = 1; i <= simulationState.numBands; i++) {
        let isOccupied = simulationState.occupiedBands.includes(i);
        simulationState.bands.push({
            id: i,
            label: `Band ${i < 10 ? '0' + i : i}`,
            state: isOccupied ? "OCCUPIED" : "IDLE",
            isOccupied: isOccupied
        });
    }

    // Reset arrays
    simulationState.history = [];
    simulationState.events = [];
    simulationState.chartHistory = {
        steps: [0],
        aiDetection: [0],
        baseDetection: [0],
        aiEnergy: [0],
        baseEnergy: [0],
        aiReward: [0],
        baseReward: [0]
    };

    logEvent("System initialized. 20 Synthetic Spectrum Channels configured.");
}

/**
 * Start or resume synthetic simulation loop
 */
function startMockSimulation(onUpdateCallback) {
    if (simulationState.running) return;

    simulationState.running = true;
    logEvent("Simulation STARTED. Executing PPO AI strategy vs Baseline.");

    // Execution timer loop
    simulationState.timerId = setInterval(() => {
        stepMockSimulation();
        if (typeof onUpdateCallback === 'function') {
            onUpdateCallback(simulationState);
        }
    }, simulationState.speedMs);
}

/**
 * Pause synthetic simulation loop
 */
function pauseMockSimulation() {
    simulationState.running = false;
    if (simulationState.timerId) {
        clearInterval(simulationState.timerId);
        simulationState.timerId = null;
    }
    logEvent("Simulation PAUSED by operator.");
}

/**
 * Reset simulation state completely
 */
function resetMockSimulation(onResetCallback) {
    pauseMockSimulation();
    initSimulation();
    if (typeof onResetCallback === 'function') {
        onResetCallback(simulationState);
    }
    logEvent("Simulation RESET to initial step 0.");
}

/**
 * Set simulation speed
 */
function setSimulationSpeed(speedMultiplier) {
    const speedMap = { 1: 1000, 2: 500, 5: 200 };
    simulationState.speedMs = speedMap[speedMultiplier] || 500;
    
    if (simulationState.running) {
        // Restart timer with new speed
        clearInterval(simulationState.timerId);
        simulationState.timerId = setInterval(() => {
            stepMockSimulation();
            if (window.onSimulationStepUpdate) {
                window.onSimulationStepUpdate(simulationState);
            }
        }, simulationState.speedMs);
    }
    logEvent(`Simulation speed set to ${speedMultiplier}x (${simulationState.speedMs}ms tick).`);
}

/**
 * Single step execution tick
 */
function stepMockSimulation() {
    simulationState.step++;

    // AI Band Selection Logic (Synthetic smart scan prioritizing active channels)
    // AI focuses on occupied channels (3, 7, 12, 18) with 75% probability, else scans others
    let selectedBand;
    if (Math.random() < 0.75) {
        const idx = Math.floor(Math.random() * simulationState.occupiedBands.length);
        selectedBand = simulationState.occupiedBands[idx];
    } else {
        selectedBand = Math.floor(Math.random() * simulationState.numBands) + 1;
    }

    simulationState.currentBand = selectedBand;

    // Update Band visual states
    simulationState.bands.forEach(band => {
        if (band.id === selectedBand) {
            band.state = "SELECTED";
        } else if (simulationState.occupiedBands.includes(band.id)) {
            band.state = "OCCUPIED";
        } else if (Math.abs(band.id - selectedBand) === 1) {
            band.state = "OBSERVED";
        } else {
            band.state = "IDLE";
        }
    });

    // Check if detection occurred on this step
    const isDetected = simulationState.occupiedBands.includes(selectedBand);

    // Realistic Synthetic Metrics Progression
    const t = simulationState.step;
    
    // AI Strategy Metric Growth Curves (Fast learning curve to ~87.4% detection, ~2.84s time, lower energy)
    const targetAIDetection = 87.4;
    const targetBaseDetection = 72.0;
    
    simulationState.aiMetrics.detectionRate = parseFloat(
        (targetAIDetection * (1 - Math.exp(-t / 30)) + (Math.random() * 1.5 - 0.75)).toFixed(1)
    );
    simulationState.baseMetrics.detectionRate = parseFloat(
        (targetBaseDetection * (1 - Math.exp(-t / 50)) + (Math.random() * 1.2 - 0.6)).toFixed(1)
    );

    // Latency Reduction Curves
    simulationState.aiMetrics.detectionTime = parseFloat(
        (2.84 + 2.16 * Math.exp(-t / 25) + (Math.random() * 0.1 - 0.05)).toFixed(2)
    );
    simulationState.baseMetrics.detectionTime = parseFloat(
        (4.80 + 0.5 * Math.exp(-t / 60) + (Math.random() * 0.1 - 0.05)).toFixed(2)
    );

    // Cumulative Energy (AI uses ~0.64 units/step vs Baseline ~1.0 unit/step)
    simulationState.aiMetrics.energyConsumption = parseFloat(
        (simulationState.aiMetrics.energyConsumption + 0.64 + Math.random() * 0.1).toFixed(1)
    );
    simulationState.baseMetrics.energyConsumption = parseFloat(
        (simulationState.baseMetrics.energyConsumption + 1.0 + Math.random() * 0.05).toFixed(1)
    );

    // Cumulative Reward (AI earns +7.5 per step on detection, Baseline +5.0)
    const aiRewardDelta = isDetected ? 8.2 : -1.2;
    const baseRewardDelta = isDetected ? 5.0 : -2.0;

    simulationState.aiMetrics.cumulativeReward = parseFloat(
        (simulationState.aiMetrics.cumulativeReward + aiRewardDelta).toFixed(1)
    );
    simulationState.baseMetrics.cumulativeReward = parseFloat(
        (simulationState.baseMetrics.cumulativeReward + baseRewardDelta).toFixed(1)
    );

    // Append history telemetry chart point
    simulationState.chartHistory.steps.push(simulationState.step);
    simulationState.chartHistory.aiDetection.push(simulationState.aiMetrics.detectionRate);
    simulationState.chartHistory.baseDetection.push(simulationState.baseMetrics.detectionRate);
    simulationState.chartHistory.aiEnergy.push(simulationState.aiMetrics.energyConsumption);
    simulationState.chartHistory.baseEnergy.push(simulationState.baseMetrics.energyConsumption);
    simulationState.chartHistory.aiReward.push(simulationState.aiMetrics.cumulativeReward);
    simulationState.chartHistory.baseReward.push(simulationState.baseMetrics.cumulativeReward);

    // Record Scan History Item
    const historyItem = {
        step: simulationState.step,
        band: `Band ${selectedBand < 10 ? '0' + selectedBand : selectedBand}`,
        strategy: "AI (PPO)",
        result: isDetected ? "DETECTED" : "NO SIGNAL",
        reward: aiRewardDelta > 0 ? `+${aiRewardDelta.toFixed(1)}` : `${aiRewardDelta.toFixed(1)}`,
        energy: (0.64 + Math.random() * 0.1).toFixed(1)
    };

    simulationState.history.unshift(historyItem);
    if (simulationState.history.length > 12) {
        simulationState.history.pop();
    }

    // Generate Console Log
    const resultMsg = isDetected ? "Synthetic Signal DETECTED" : "Channel Clear";
    logEvent(`Step ${simulationState.step}: AI selected Band ${selectedBand} &bull; ${resultMsg}`);
}

/**
 * Log message helper
 */
function logEvent(message) {
    const timestamp = new Date().toTimeString().split(' ')[0];
    const logLine = `[${timestamp}] ${message}`;
    simulationState.events.unshift(logLine);
    if (simulationState.events.length > 50) {
        simulationState.events.pop();
    }
}
